<script setup lang="ts">import{createGradientController}from'@fex-design/core/gradient/create-gradient-controller';import type{GradientChangeDetail,GradientOptions,LinearGradientInput,LinearGradientValue}from'@fex-design/core/gradient/types';import{computed,provide}from'vue';import{useCoreStore}from'../../composables/use-core-store';import{gradientPickerKey}from'./context';const props=defineProps<{value?:LinearGradientInput;defaultValue?:LinearGradientInput;disabled?:boolean}>();const emit=defineEmits<{change:[value:LinearGradientValue,detail:GradientChangeDetail];changeComplete:[value:LinearGradientValue,detail:GradientChangeDetail]}>();const options:GradientOptions={get value(){return props.value},get defaultValue(){return props.defaultValue},get disabled(){return props.disabled},onChange:(v,d)=>emit('change',v,d),onChangeComplete:(v,d)=>emit('changeComplete',v,d)};const controller=createGradientController(options),store=useCoreStore(controller),snapshot=computed(()=>{void store.value;return controller.getSnapshot()});provide(gradientPickerKey,{controller,snapshot})</script><template><slot :controller="controller" :snapshot="snapshot"/></template>
